-- Proof: Cindra is a REAL ribbon world generated by the MAP-GEN itself, now with
-- the PER-ZONE gradient (ci-3yl; per-zone widths + hot-lava + ice cliff, ci-a35).
--
-- No on_chunk_generated script paints or voids anything. This drives the actual
-- planet map_gen_settings on a fresh, fixed-seed surface and proves, on the
-- default vertical orientation (ribbon long axis = Y; hot-cold gradient = X, hot
-- on the LEFT / west, perp = -x):
--   1. FINITE PERPENDICULAR: the map-gen's own `width` = the SUM of every zone
--      width voids everything beyond +/- sum/2 (out-of-map), interior playable.
--   2. PER-ZONE TILE BANDS hot->cold, each cindra-* tile in its band; hot-lava is
--      ALWAYS at the hot edge; the default band widths (80/40/30/.../20) hold.
--   3. ZERO NAUVIS LEAKAGE: no grass, no water.
--   4. ICE CLIFF: a continuous impassable wall on the rough/smooth-ice boundary.
--   5. SPAWN on the wide sand band.
--   6. NATIVE RESOURCES (unchanged): stone hot side, ice nightside, banded rocks.
--
-- The pure band geometry is proven in unit-tests/test_terrain + test_resource_field;
-- this proves it actually generates on a live surface.

local field = require("scripts.resource-field")
local terrain = require("scripts.terrain")
local zones = require("scripts.zones")

describe("cindra worldgen: a real per-zone ribbon world (§4, §15-2; ci-a35)", function()
  -- A dedicated surface cloned from the Cindra planet's own map_gen_settings (same
  -- finite width, tile bands, resource controls, cliff) at a FIXED seed, so
  -- generation is reproducible and isolated from tests that pave the shared
  -- "cindra" surface. The tile bands use fixed noise seeds, so they are
  -- seed-independent; the fixed seed pins the resource patches.
  local s
  local ready = false
  local RX, RY = 200, 300
  local L = zones.layout()
  local HALF = L.half

  before_each(function()
    if ready then return end
    local base = game.surfaces["cindra"]
      or (game.planets["cindra"] and game.planets["cindra"].create_surface())
    local mgs = base.map_gen_settings
    mgs.seed = 2468
    -- The finite perpendicular bound is applied to a Cindra surface when created
    -- (scripts/driver.enforce_finite). This dedicated surface isn't named "cindra",
    -- so replicate exactly what the hook does so the void + bands generate identically.
    local fd = terrain.finite_dimension()
    mgs[fd.key] = fd.value
    s = game.surfaces["cindra-worldgen-test"] or game.create_surface("cindra-worldgen-test", mgs)
    s.request_to_generate_chunks({ 0, 0 }, 13) -- ~416-tile radius: covers the whole region
    s.force_generate_chunk_requests()
    ready = true
  end)

  local function tile(x, y) return s.get_tile(x, y).name end

  -- 1. FINITE PERPENDICULAR via the map-gen (width = SUM of zone widths) ----------
  it("is finite perpendicular: width = the sum of zone widths; voids beyond, interior playable", function()
    assert.are.equal(360, HALF * 2, "default sum of zone widths is 360")
    assert.are.equal("out-of-map", tile(-(HALF + 8), 0), "sunward (west) beyond the band is void")
    assert.are.equal("out-of-map", tile(HALF + 8, 0), "nightward (east) beyond the band is void")
    assert.are_not.equal("out-of-map", tile(0, 0), "the interior is playable")
    assert.are_not.equal("out-of-map", tile(-(HALF - 5), 0), "the hot extreme is still land")
    assert.are_not.equal("out-of-map", tile(HALF - 5, 0), "the cold extreme is still land")
  end)

  -- 2. PER-ZONE TILE BANDS, hot -> cold across the X axis (perp = -x) -------------
  -- Sample the CENTRE of each band (well clear of the wiggled boundaries). x = -p.
  local function band_center_x(name)
    for _, z in ipairs(L.zones) do if z.name == name then return -z.center_p end end
  end

  it("lays the per-zone tile bands hot-lava -> ... -> smooth-ice across the axis", function()
    assert.are.equal("cindra-hot-lava",    tile(band_center_x("hot-lava"), 0),    "hot-lava at the hot extreme")
    assert.are.equal("cindra-lava-field",  tile(band_center_x("lava"), 0),        "lava band")
    assert.are.equal("cindra-cracks-hot",  tile(band_center_x("cracks-hot"), 0),  "scorched cracks band")
    assert.are.equal("cindra-sand",        tile(band_center_x("sand"), 0),        "the wide sand spawn band")
    assert.are.equal("cindra-rough-ice",   tile(band_center_x("rough-ice"), 0),   "rough-ice band")
    assert.are.equal("cindra-smooth-ice",  tile(band_center_x("smooth-ice"), 0),  "smooth-ice band")
    -- aquilo-dust is a VARIED band: any of its variants counts.
    local dust = tile(band_center_x("aquilo-dust"), 0)
    assert.is_true(dust == "cindra-aquilo-dust-1" or dust == "cindra-aquilo-dust-2"
      or dust == "cindra-aquilo-dust-3", "frost-dust band (a varied Aquilo dust tile); got " .. dust)
  end)

  it("ALWAYS generates a hot-lava band at the hot edge (ci-a35 item 2)", function()
    -- The very hot extreme (just inside the void) is hot-lava, on every row.
    for _, y in ipairs({ -200, -80, 0, 80, 200 }) do
      assert.are.equal("cindra-hot-lava", tile(-(HALF - 3), y),
        "the hot extreme is hot-lava at y=" .. y)
    end
  end)

  it("the default band widths hold: hot-lava ~80 at the left edge, lava ~40, cracks-hot ~30", function()
    -- Scan a single row from the hot edge inward; measure each leading band's run.
    local function first_x_of(name)
      for x = -HALF, HALF do if tile(x, 0) == name then return x end end
      return nil
    end
    local function last_x_of_leading(name, from)
      local x = from
      while x <= HALF and tile(x, 0) == name do x = x + 1 end
      return x - 1
    end
    local hl0 = first_x_of("cindra-hot-lava")
    assert.is_not_nil(hl0, "hot-lava present")
    assert.is_true(hl0 <= -(HALF - 10), "hot-lava starts at the hot edge (x~=-180)")
    -- hot-lava default width 80: its run ends around x = -100 (+/- the noise wiggle).
    local hl_end = last_x_of_leading("cindra-hot-lava", hl0)
    assert.is_true(hl_end >= -(HALF) + 80 - 12 and hl_end <= -(HALF) + 80 + 12,
      "hot-lava band is ~80 wide at the left edge; ended at x=" .. hl_end)
  end)

  it("draws ORGANIC (wavy) band boundaries, never raw straight lines", function()
    -- Where does hot-lava first give way to lava, scanning inward per row? A straight
    -- line => identical x on every row; the basis_noise wiggle makes it VARY.
    local first_lava = {}
    for y = -120, 120, 12 do
      for x = -(HALF - 20), 0 do
        if tile(x, y) == "cindra-lava-field" then first_lava[#first_lava + 1] = x; break end
      end
    end
    assert.is_true(#first_lava >= 8, "sampled enough rows to judge the boundary")
    local lo, hi = first_lava[1], first_lava[1]
    for _, x in ipairs(first_lava) do if x < lo then lo = x end; if x > hi then hi = x end end
    assert.is_true(hi - lo >= 3, "the boundary wanders across rows (organic); spread=" .. (hi - lo))
  end)

  -- 3. ZERO NAUVIS LEAKAGE --------------------------------------------------------
  it("generates NO grass and NO water anywhere (no nauvis terrain leakage)", function()
    local box = { { -RX, -RY }, { RX, RY } }
    for _, n in ipairs({ "grass-1", "grass-2", "grass-3", "grass-4", "water", "deepwater" }) do
      assert.are.equal(0, s.count_tiles_filtered({ name = n, area = box }), "Cindra must generate no " .. n)
    end
  end)

  it("paints ONLY Cindra tiles across the interior (every band is a cindra-* tile)", function()
    local cindra_set = {}
    for _, n in ipairs(terrain.tile_names()) do cindra_set[n] = true end
    for x = -(HALF - 10), HALF - 10, 20 do
      for y = -120, 120, 40 do
        local n = tile(x, y)
        assert.is_true(cindra_set[n] == true,
          "interior tile at (" .. x .. "," .. y .. ") must be a Cindra tile, got " .. n)
      end
    end
  end)

  -- 4. ICE CLIFF wall on the rough/smooth-ice boundary ----------------------------
  it("runs a continuous impassable ICE CLIFF along the rough/smooth-ice boundary", function()
    local cliff_x = -L.cliff_p -- p -> x
    -- Cliffs cluster on the boundary line (a thin x strip), not scattered elsewhere.
    local on_line = s.count_entities_filtered({
      name = "cindra-ice-cliff", area = { { cliff_x - 10, -RY }, { cliff_x + 10, RY } } })
    assert.is_true(on_line > 0, "an ice cliff forms on the rough/smooth boundary (x~=" .. cliff_x .. ")")
    -- Continuity: the wall spans the long axis. Check several disjoint y-bands each
    -- carry a cliff piece near the boundary line.
    local covered = 0
    for y0 = -RY, RY - 60, 60 do
      local n = s.count_entities_filtered({
        name = "cindra-ice-cliff", area = { { cliff_x - 10, y0 }, { cliff_x + 10, y0 + 60 } } })
      if n > 0 then covered = covered + 1 end
    end
    assert.is_true(covered >= 8, "the ice cliff is continuous along the ribbon; covered " .. covered .. " y-bands")
  end)

  -- 5. SPAWN on the sand band -----------------------------------------------------
  it("puts the world spawn on the wide sand band", function()
    local sp = terrain.spawn_position()
    assert.are.equal("cindra-sand", tile(sp.x, sp.y), "the spawn tile is sand")
    -- and the real cindra surface's force spawn was moved there by the driver.
    local live = game.surfaces["cindra"]
      or (game.planets["cindra"] and game.planets["cindra"].create_surface())
    local sp2 = game.forces["player"].get_spawn_position(live)
    assert.is_true(math.abs(sp2.x - sp.x) < 2 and math.abs(sp2.y - sp.y) < 2,
      "the player force spawns on the sand band")
  end)

  -- 6. NATIVE RESOURCES, banded to the ribbon axis (resource-field unchanged) -----
  local function count(name, x1, x2)
    return s.count_entities_filtered({ name = name, area = { { x1, -RY }, { x2, RY } } })
  end

  it("places stone as patches on the ribbon + hot side, never deep nightward", function()
    assert.is_true(count(field.STONE, -96, 24) > 0, "stone patches in the stone band")
    assert.are.equal(0, count(field.STONE, 40, 128), "no stone deep nightward (east)")
  end)

  it("places ice as patches on the nightside, never sunward of the safe band", function()
    assert.is_true(count(field.ICE, 30, 128) > 0, "ice patches on the nightside (east)")
    assert.are.equal(0, count(field.ICE, -128, 0), "no ice sunward (west) of the safe band")
  end)

  it("scatters bootstrap rocks across the WHOLE ribbon band, not just near spawn (ci-9bb)", function()
    local near = s.count_entities_filtered({ name = field.ROCK, area = { { -24, -100 }, { 24, 100 } } })
    assert.is_true(near > 0, "bootstrap rocks scatter around the terminator")
    local far = s.count_entities_filtered({ name = field.ROCK, area = { { -24, 150 }, { 24, RY } } })
    assert.is_true(far > 0, "bootstrap rocks also generate far down the ribbon")
    local outside = s.count_entities_filtered({ name = field.ROCK, area = { { 40, -100 }, { 120, 100 } } })
    assert.are.equal(0, outside, "no rocks out past the safe band")
  end)

  it("the ice field reads as ICY on the map: pale cyan/frost map_color (ci-9bb)", function()
    local ice = prototypes.entity["cindra-ice"].map_color
    assert.is_not_nil(ice, "the ice resource has a map_color")
    assert.is_true(ice.b >= 0.85 and ice.g >= 0.8, "ice map_color is a bright cyan/frost tone")
    assert.is_true(ice.b > ice.r and ice.g > ice.r, "ice map_color is cool (blue+green over red)")
    local stone = prototypes.entity["cindra-stone"].map_color
    assert.is_true(stone.r > stone.b, "sanity: stone is a warm tone")
    assert.is_true(ice.b > stone.b + 0.3, "ice is clearly icier/bluer than the warm stone patch")
    local iron = prototypes.entity["iron-ore"].map_color
    assert.is_true(ice.r + ice.g + ice.b > iron.r + iron.g + iron.b + 0.6,
      "ice map_color is markedly paler/brighter than iron ore's steel-blue")
    assert.is_true(ice.g > iron.g + 0.25, "ice map_color is more cyan than iron ore")
  end)

  it("bounds the REAL cindra planet surface at creation: width = sum of zone widths", function()
    local live = game.surfaces["cindra"]
      or (game.planets["cindra"] and game.planets["cindra"].create_surface())
    local mg = live.map_gen_settings
    assert.are.equal(360, mg.width, "the cindra surface is finite perpendicular (width = sum)")
    assert.is_true(mg.height == 0 or mg.height > 100000,
      "the ribbon is infinite along its long (Y) axis; got height=" .. tostring(mg.height))
  end)

  it("exposes real map-gen sliders (Stone + Ice only, no standalone volatiles)", function()
    for _, n in ipairs({ "cindra-stone", "cindra-ice" }) do
      local ctrl = prototypes.autoplace_control[n]
      assert.is_not_nil(ctrl, n .. " autoplace-control exists")
      assert.are.equal("resource", ctrl.category, n .. " is a resource slider")
    end
    assert.is_nil(prototypes.autoplace_control["cindra-volatiles"], "no standalone volatiles slider")
    assert.is_nil(prototypes.entity["cindra-volatiles"], "no standalone volatiles resource entity")
    assert.is_not_nil(prototypes.item["cindra-volatiles"], "the volatiles item survives")
  end)

  it("the ice field is a single-product drop: ONLY the oxide chunk, no volatiles (ci-4xx)", function()
    local products = prototypes.entity["cindra-ice"].mineable_properties.products
    local names = {}
    for _, p in ipairs(products) do names[p.name] = true end
    assert.is_true(names["oxide-asteroid-chunk"], "the ice field still yields the vanilla oxide chunk")
    assert.is_nil(names["cindra-volatiles"], "mining the ice field must NOT drop volatiles")
    assert.are.equal(1, #products, "the ice field is a single-product resource")
  end)
end)
